<!DOCTYPE html>
<html>
<head>
<title>Personal Expense Tracker</title>
<style>
body { font-family: sans-serif; }
.expense { border: 1px solid #ccc; padding: 10px; margin-bottom: 5px; }
.cat-total { font-weight: bold; margin-right: 5px; }
#form-error { color: red; margin-top: 5px; }
</style>
</head>
<body>

<h1>Personal Expense Tracker</h1>

<form id="expense-form">
  <label for="#amount">Amount:</label>
  <input type="number" id="amount" step="0.01"><br><br>

  <label for="#category">Category:</label>
  <select id="category">
    <option value="groceries">Groceries</option>
    <option value="transport">Transport</option>
    <option value="bills">Bills</option>
    <option value="fun">Fun</option>
  </select><br><br>

  <label for="#date">Date:</label>
  <input type="date" id="date"><br><br>

  <label for="#note">Note (optional):</label>
  <textarea id="note"></textarea><br><br>

  <button id="add-expense">Add Expense</button>
  <p id="form-error"></p>
</form>

<h2>Expenses</h2>
<ul id="expenses"></ul>

<div class="cat-total" data-cat="groceries">0.00</div>
<div class="cat-total" data-cat="transport">0.00</div>
<div class="cat-total" data-cat="bills">0.00</div>
<div class="cat-total" data-cat="fun">0.00</div>

<hr>

<h3>Filters</h3>
<label for="#filter-category">Category:</label>
<select id="filter-category">
  <option value="all">All</option>
</select><br>

<label for="#filter-from">From:</label>
<input type="date" id="filter-from"><br>

<label for="#filter-to">To:</label>
<input type="date" id="filter-to"><br>

<h2>Total: <span id="total">0.00</span></h2>


<script>
const expenseForm = document.getElementById('expense-form');
const expensesList = document.getElementById('expenses');
const totalSpan = document.getElementById('total');
const formErrorElement = document.getElementById('form-error');
const filterCategorySelect = document.getElementById('filter-category');
const filterFromInput = document.getElementById('filter-from');
const filterToInput = document.getElementById('filter-to');

let expenses = [];

function loadExpenses() {
  const storedExpenses = localStorage.getItem('expenses');
  if (storedExpenses) {
    expenses = JSON.parse(storedExpenses);
  }
  renderExpenses();
  updateTotal();
  updateCategoryTotals();
}

function renderExpenses() {
  expensesList.innerHTML = '';
  const filteredExpenses = expenses.filter(expense => {
    const fromFilter = filterFromInput.value ? new Date(expense.date) >= new Date(filterFromInput.value) : true;
    const toFilter = filterToInput.value ? new Date(expense.date) <= new Date(filterToInput.value) : true;
    const categoryFilter = filterCategorySelect.value === 'all' || expense.category === filterCategorySelect.value;

    return fromFilter && toFilter && categoryFilter;
  });

  filteredExpenses.sort((a, b) => new Date(b.date) - new Date(a.date));

  filteredExpenses.forEach(expense => {
    const listItem = document.createElement('li');
    listItem.className = 'expense';
    listItem.innerHTML = `
      ${expense.amount.toFixed(2)} ${expense.category} - ${expense.date} 
      <button class="exp-del" data-id="${expense.id}">Delete</button>
    `;
    expensesList.appendChild(listItem);
  });
}

function updateTotal() {
  const filteredExpenses = expenses.filter(expense => {
    const fromFilter = filterFromInput.value ? new Date(expense.date) >= new Date(filterFromInput.value) : true;
    const toFilter = filterToInput.value ? new Date(expense.date) <= new Date(filterToInput.value) : true;
    const categoryFilter = filterCategorySelect.value === 'all' || expense.category === filterCategorySelect.value;

    return fromFilter && toFilter && categoryFilter;
  });
  const total = filteredExpenses.reduce((sum, expense) => sum + expense.amount, 0);
  totalSpan.textContent = total.toFixed(2);
}


function updateCategoryTotals() {
  const filteredExpenses = expenses.filter(expense => {
    const fromFilter = filterFromInput.value ? new Date(expense.date) >= new Date(filterFromInput.value) : true;
    const toFilter = filterToInput.value ? new Date(expense.date) <= new Date(filterToInput.value) : true;
    const categoryFilter = filterCategorySelect.value === 'all' || expense.category === filterCategorySelect.value;

    return fromFilter && toFilter && categoryFilter;
  });

  const categoryTotals = {};
  filteredExpenses.forEach(expense => {
    if (!categoryTotals[expense.category]) {
      categoryTotals[expense.category] = 0;
    }
    categoryTotals[expense.category] += expense.amount;
  });

  for (const category in categoryTotals) {
    const element = document.querySelector(`[data-cat="${category}"]`);
    if (element) {
      element.textContent = categoryTotals[category].toFixed(2);
    }
  }
}



function addExpense() {
  const amount = parseFloat(document.getElementById('amount').value);
  const category = document.getElementById('category').value;
  const date = document.getElementById('date').value;
  const note = document.getElementById('note').value;

  if (isNaN(amount) || !date) {
    formErrorElement.textContent = 'Please enter a valid amount and date.';
    return;
  }

  if (amount <= 0) {
    formErrorElement.textContent = 'Amount must be greater than zero.';
    return;
  }

  const expense = { id: Date.now(), amount, category, date, note };
  expenses.push(expense);

  localStorage.setItem('expenses', JSON.stringify(expenses));
  renderExpenses();
  updateTotal();
  updateCategoryTotals();
  formErrorElement.textContent = '';
  document.getElementById('amount').value = '';
}


expensesList.addEventListener('click', (event) => {
    if (event.target.classList.contains('exp-del')) {
        const id = event.target.dataset.id;
        const index = expenses.findIndex(expense => expense.id === parseInt(id));

        if (index !== -1) {
            expenses.splice(index, 1);
            localStorage.setItem('expenses', JSON.stringify(expenses));
            renderExpenses();
            updateTotal();
            updateCategoryTotals();
        }
    }
});


loadExpenses();

expenseForm.addEventListener('submit', (event) => {
  event.preventDefault();
  addExpense();
});

filterCategorySelect.addEventListener('change', () => {
  renderExpenses();
  updateTotal();
  updateCategoryTotals();
});

filterFromInput.addEventListener('change', () => {
    renderExpenses();
    updateTotal();
    updateCategoryTotals();
});

filterToInput.addEventListener('change', () => {
    renderExpenses();
    updateTotal();
    updateCategoryTotals();
});

</script>

</body>
</html>
